    let epoch: i64 = c.query_row(
        "SELECT inventory_visibility_epoch FROM relay_runtime WHERE singleton=1",
        [],
        |r| r.get(0),
    )?;
    c.execute(
        "UPDATE relay_runtime SET inventory_visibility_epoch=?1 WHERE singleton=1",
        [next(epoch)?],
    )?;
    Ok(())
}
