        &self,
        channel: &mut SecureChannel<IO>,
        proof: &ProofContext,
        view: &InventoryView,
        lease: &SessionLease,
        claimed_equal: bool,
    ) -> Result<(), IndexedRelayError> {
        let mut eligible = claimed_equal && self.stamp_matches(proof.local)?;
