                Ok(equal) => equal,
                Err(LogError::StaleCursor) => false,
                Err(error) => return Err(error.into()),
            };
        }
        eligible = eligible && self.stamp_matches(proof.local)?;
        send_frame(channel, &encode_flag(ACK, eligible)).await?;
        if eligible {
            self.conditional.remember(proof);
        }
        Ok(())
    }
