};

const LIMIT: usize = 64;
const NAMES: [&str; 12] = [
    "other",
    "participant_sync",
    "file_receive",
    "file_download",
    "file_consent",
    "channel",
    "events",
    "media",
    "relay",
    "reclaim",
    "checkpoint",
    "schema",
];
const FAMILIES: usize = NAMES.len();
struct Entry {
    id: u64,
    last: u64,
    family: usize,
    pages: [u64; FAMILIES],
}
#[derive(Default)]
struct State {
    next: u64,
    entries: BTreeMap<usize, Entry>,
    closed: Vec<Entry>,
    overflow_pages: u64,
}
fn state() -> &'static Mutex<State> {
    static STATE: OnceLock<Mutex<State>> = OnceLock::new();
    STATE.get_or_init(Default::default)
}
fn retire(s: &mut State, entry: Entry) {
    if entry.pages.iter().all(|pages| *pages == 0) {
        return;
    }
    if s.closed.len() == LIMIT {
        let old = s.closed.remove(0);
        s.overflow_pages = old
            .pages
            .iter()
            .fold(s.overflow_pages, |sum, n| sum.saturating_add(*n));
    }
    s.closed.push(entry);
}
