                || invalid_completion
            {
                return Ok(true);
            }
            let accepted = {
                let mut store = self.file_consent.lock().expect("file consent lock");
                if direct {
                    store.receive_direct_control(event.clone())?
                } else {
                    store.receive_control(event.clone())?
                }
