                self.note_file_change();
                if payload.decision == ReceiveDecision::Accepted && payload.completion.is_none() {
                    self.request_group_file_custody(
                        original.conversation_id,
                        payload.file,
                        payload.manifest,
                        peer,
                        event.id,
                    );
                }
            }
            return Ok(true);

